export const handler = async (input) => {
  // 从输入的原始 JSON 中安全获取 items 数组
  const items = input.items || [];
  
  // 1. 核心循环：把所有 goodsName 用“、”拼接在一起
  const resultText = items
    .map(item => item?.goodsName || '')
    .filter(name => name !== '')
    .join('、');

  // 2. 核心循环：精简字段，清洗多余的杂乱字段
  const cleanedItems = items.map(item => {
    // 将字符串形式的金额（如 "476.1"）安全转换为真正的数字（支持小数）
    const parsedAmount = item?.detailAmount ? parseFloat(item.detailAmount) : 0;
    
    return {
      goodsName: item?.goodsName || '',
      detailAmount: isNaN(parsedAmount) ? 0 : parsedAmount  // 确保万无一失不出现 NaN
    };
  });

  // 3. 统一返回你需要的所有结果
  return {

    contents: resultText || '无',
    filtered_items: cleanedItems,
    remark: input.remark ?? '',
    invoiceAmount: parseFloat(input.invoiceAmount),
    context: input.context || {}
  };
};

export const handler = async (input) => {
  const context = input.context || {};
  const remark = input.remark ?? context.remark ?? '';

  // 从 submitTime 提取提交年份，计算前一年
  const submitTime = context.serviceData?.auditInfo?.submitTime ?? '';
  let submitYear = null;
  if (submitTime) {
    const match = String(submitTime).match(/(\d{4})/);
    if (match) {
      submitYear = parseInt(match[1], 10) - 1;
    }
  }
  const submitYearStr = submitYear !== null ? String(submitYear) : '未知';
  const thresholdMonth = submitYear !== null ? submitYear * 100 + 12 : null;

  const optimizedPrompt = `# Role
你是一名严谨的电信发票备注信息审核助手。

# Task
请根据【remark】字段内容，完成以下任务：
1. remarkPhone: 提取用户实际使用的中国大陆 11 位手机号。
2. isInvoiceYearMatched: 判断账期中是否包含提交年份前一年的12月及之后的账期。
3. matchReason: 给出判断原因。

# 关键变量（已注入）
- submitYear（提交年份的前一年）: ${submitYearStr}
- 账期匹配阈值（前一年12月）: ${thresholdMonth !== null ? thresholdMonth : '未知'}
  - 例如 submitYear=2025，则阈值=202512，需要检查是否有 >= 202512 的账期
  - 例如 submitYear=2024，则阈值=202412，需要检查是否有 >= 202412 的账期

# Rules
- 优先提取"业务号码""手机号码""用户号码""联系电话"等标签对应的 11 位手机号。
- 排除 10000、10010、10086 等客服短号，排除座机、发票代码、税号、流水号等非手机号数字。
- 如果手机号中有空格、短横线或其他分隔符，请去掉分隔符后返回连续 11 位数字。
- 若无法确定手机号，remarkPhone 返回空字符串。
- isInvoiceYearMatched 判断规则：
  - 提取 remark 中所有账期月份（YYYYMM 格式），检查是否有任何一个月份 >= 阈值月份（${thresholdMonth !== null ? thresholdMonth : '未知'}）
  - 如果有，返回 true；否则返回 false
  - 如果无法确定 submitYear 或无法解析账期，返回 false
- matchReason 必须清晰说明判断依据，例如：
  - "账期包含 202512（>= 阈值 202512），匹配成功"
  - "所有账期均 < 阈值 202512，不匹配"
  - "无法识别账期信息，默认不匹配"

# Examples
- remark: 业务号码:15652828661;账期:202512-202603
  submitYear=2025, threshold=202512
  output: {"remarkPhone":"15652828661","isInvoiceYearMatched":true,"matchReason":"账期包含 202512（>= 阈值 202512），匹配成功"}
- remark: 用户号码 156 5282 8661，计费周期 2025年12月01日至2026年03月31日
  submitYear=2025, threshold=202512
  output: {"remarkPhone":"15652828661","isInvoiceYearMatched":true,"matchReason":"账期包含 202512（>= 阈值 202512），匹配成功"}
- remark: 账期:202504,202505,202506
  submitYear=2025, threshold=202512
  output: {"remarkPhone":"","isInvoiceYearMatched":false,"matchReason":"所有账期 202504,202505,202506 均 < 阈值 202512，不匹配"}
- remark: 账期:202511-202512
  submitYear=2025, threshold=202512
  output: {"remarkPhone":"","isInvoiceYearMatched":true,"matchReason":"账期包含 202512（>= 阈值 202512），匹配成功"}

# Output
你必须只返回 JSON，不要输出任何解释、前后缀或 Markdown。

JSON 结构严格如下：
{
  "remarkPhone": "11位手机号，未识别时为空字符串",
  "isInvoiceYearMatched": true 或 false,
  "matchReason": "判断原因的详细说明"
}

# Input Remark
${remark}`;

  return {

    prompt: optimizedPrompt,
    submitYear: submitYear,
    thresholdMonth: thresholdMonth,
    context: input.context || {}
  };
};

import http from 'http';

const LOCAL_LLM_URL = 'http://172.16.3.231:8091/api/v1/node-gateway/llm/evaluate';

export const handler = async (input) => {
  try {
    const context = input && input.context ? input.context : {};
    const prompt = input.prompt || context.prompt || (input.prev && input.prev.prompt) || '';

    if (!prompt) {
      throw new Error('missing prompt from previous component output');
    }

    const payload = {
      prompt
    };

    if (input.systemPrompt || context.systemPrompt) {
      payload.systemPrompt = input.systemPrompt || context.systemPrompt;
    }

    if (input.model || context.llmModel) {
      payload.model = input.model || context.llmModel;
    }

    if (typeof input.temperature === 'number' || typeof context.temperature === 'number') {
      payload.temperature = typeof input.temperature === 'number' ? input.temperature : context.temperature;
    }

    if (input.context && input.context.runId) { payload.runId = input.context.runId; }
    if (input.context && input.context.receiptCode) { payload.receiptCode = input.context.receiptCode; }
    if (input.context && input.context.invoiceKey) { payload.invoiceKey = input.context.invoiceKey; }
    const response = await http.post(LOCAL_LLM_URL, payload);

    if (!response || response.status < 200 || response.status >= 300) {
      throw new Error('local llm service failed at ' + LOCAL_LLM_URL + ': ' + (response && response.status ? response.status : 'unknown'));
    }

    const result = typeof response.data === 'string' ? JSON.parse(response.data) : (response.data || {});

    return {
      llm_status: result.llmStatus || 'error',
      llm_result: result.llmResult || null,
      raw_content: result.rawContent || null,
      error_message: result.errorMessage || null
    };
  } catch (error) {
    return {
      llm_status: 'error',
      error_message: error && error.message ? error.message : String(error)
    };
  }
};

export const handler = async (input) => {
  // 1. 深度兼容获取拼接好的发票商品内容字符串（兼容顶级和 context 结构）
  const context = input.context || {};
  const contents = input.contents ?? context.contents ?? '无';

  // 2. 结构化、极度严谨的专家级提示词组装
  const optimizedPrompt = `# Role
你是一位极其严谨的企业财税合规审计专家，负责审查发票商品内容（发票内容）中是否包含公司明令禁止报销的“预付、充值、储值类卡券”项目。

# 核心审查规则
请仔细阅读给出的【发票内容】。如果内容中包含、涉及或暗示了“预付卡销售”、“话费充值”、“卡券购买”、“预存、储值”等资金前置占用的非即期消费行为，则判定为【不合规】；如果是正常的单次通信服务费、宽带费或实物消费，则判定为【合规】。

# 核心判据清单
- 【不合规（Passed = false）的特征】词：预付卡、单用途卡、充值、充值卡、预存、储值、面值、卡券。
- 【合规（Passed = true）的特征】词：通信服务费、信息服务费、话费、宽带费、月租费、套餐费。

# 示例参考 (Few-Shot)
- 输入：*电信服务*通信服务费 ➡️ 返回：{"passed": true}
- 输入：*电信服务*话费充值 ➡️ 返回：{"passed": false}
- 输入：*现代服务*预付卡销售 ➡️ 返回：{"passed": false}
- 输入：*电信服务*违约金 ➡️ 返回：{"passed": false}

# 极其严格的输出格式要求
你必须【仅仅且直接】返回一个标准的 JSON 对象，严禁包含任何前言、后记、Markdown 标记（如 json 块标签）或多余的文字解释。

JSON 结构必须严格如下：
{
  "passed": 判定结果（布尔类型 true 或 false，不要带引号）
}

# 待审查的真实数据
发票内容是：${contents}`;

  // 3. 返回高准确率的最终大模型提示词
  return {

    prompt: optimizedPrompt,
    context: input.context || {}
  };
};

